import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { appRoutes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideHttpClient(),
    provideRouter(appRoutes),
    provideNativeDateAdapter(),
  ],
};
export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Movie, Screening } from './models';

export const API_BASE_URL = 'http://localhost:3000';

@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient);

  getMovies(): Observable<Movie[]> {
    return this.http.get<Movie[]>(`${API_BASE_URL}/movies`);
  }

  getScreeningsByDate(date: string): Observable<Screening[]> {
    return this.http.get<Screening[]>(`${API_BASE_URL}/screenings`, { params: { date } });
  }
}
const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

/** Formats a date as an ISO date (YYYY-MM-DD) using the browser's local calendar. */
export function toIsoDate(date: Date): string {
  const year = String(date.getFullYear()).padStart(4, '0');
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/** Parses a YYYY-MM-DD string into a local midnight Date; returns null for anything that is not a real calendar date. */
export function parseIsoDate(value: string | null | undefined): Date | null {
  if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return null;
  }
  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  if (toIsoDate(date) !== value) {
    return null;
  }
  return date;
}

/** Local midnight of the given date. */
export function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

/** Returns the date `days` days after `date`. */
export function addDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

/** English full weekday name, e.g. "Tuesday". */
export function weekdayName(date: Date): string {
  return WEEKDAYS[date.getDay()];
}

import { Component, computed, inject, resource } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatButtonModule } from '@angular/material/button';
import { MatCardModule } from '@angular/material/card';
import { MatDatepickerModule } from '@angular/material/datepicker';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { firstValueFrom, forkJoin } from 'rxjs';
import { ApiService } from '../api.service';
import { addDays, parseIsoDate, startOfDay, toIsoDate, weekdayName } from '../dates';
import { Movie, Screening } from '../models';

interface DayButton {
  iso: string;
  label: string;
}

interface MovieCard {
  movie: Movie;
  screenings: Screening[];
}

@Component({
  selector: 'app-movie-list',
  imports: [MatButtonModule, MatCardModule, MatDatepickerModule, MatFormFieldModule, MatInputModule, RouterLink],
  templateUrl: './movie-list.html',
  styleUrl: './movie-list.scss',
})
export class MovieList {
  private readonly api = inject(ApiService);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  private readonly today = startOfDay(new Date());
  private readonly todayIso = toIsoDate(this.today);

  readonly minDate = this.today;

  readonly dayButtons: DayButton[] = [0, 1, 2, 3, 4].map((offset) => {
    const date = addDays(this.today, offset);
    return { iso: toIsoDate(date), label: offset === 0 ? 'Today' : weekdayName(date) };
  });

  private readonly queryParams = toSignal(this.route.queryParamMap, { requireSync: true });

  /** The selected day as ISO date; a missing, invalid or past `date` selects today. */
  readonly selectedIso = computed(() => {
    const requested = this.queryParams().get('date');
    if (requested === null || parseIsoDate(requested) === null || requested < this.todayIso) {
      return this.todayIso;
    }
    return requested;
  });

  readonly selectedDate = computed(() => parseIsoDate(this.selectedIso()));

  readonly movies = resource({
    params: () => this.selectedIso(),
    loader: ({ params: date }) =>
      firstValueFrom(
        forkJoin({
          movies: this.api.getMovies(),
          screenings: this.api.getScreeningsByDate(date),
        }),
      ),
  });

  /** One card per movie with at least one screening on the selected day, in backend order. */
  readonly cards = computed<MovieCard[]>(() => {
    if (!this.movies.hasValue()) {
      return [];
    }
    const { movies, screenings } = this.movies.value();
    return movies
      .map((movie) => ({
        movie,
        screenings: screenings
          .filter((screening) => screening.movieId === movie.id)
          .sort((a, b) => a.time.localeCompare(b.time)),
      }))
      .filter((card) => card.screenings.length > 0);
  });

  retry(): void {
    this.movies.reload();
  }

  selectDay(iso: string): void {
    this.navigateToDate(iso);
  }

  onDatepickerChange(date: Date | null): void {
    if (!date) {
      return;
    }
    const iso = toIsoDate(date);
    this.navigateToDate(iso < this.todayIso ? this.todayIso : iso);
  }

  private navigateToDate(iso: string): void {
    void this.router.navigate([], { relativeTo: this.route, queryParams: { date: iso } });
  }
}
<section class="day-picker" data-testid="day-picker">
  @for (day of dayButtons; track day.iso) {
    <button
      mat-stroked-button
      data-testid="day-button"
      [attr.data-date]="day.iso"
      [attr.data-selected]="day.iso === selectedIso()"
      [color]="day.iso === selectedIso() ? 'primary' : undefined"
      (click)="selectDay(day.iso)"
    >
      {{ day.label }}
    </button>
  }

  <mat-form-field appearance="outline" subscriptSizing="dynamic">
    <mat-label>Other date</mat-label>
    <input
      matInput
      data-testid="date-picker"
      [matDatepicker]="picker"
      [min]="minDate"
      [value]="selectedDate()"
      (dateChange)="onDatepickerChange($event.value)"
      (click)="picker.open()"
      readonly
    />
    <mat-datepicker-toggle matIconSuffix [for]="picker" />
    <mat-datepicker #picker />
  </mat-form-field>
</section>

@if (movies.isLoading()) {
  <p class="status" data-testid="movies-loading">Loading…</p>
} @else if (movies.status() === 'error') {
  <div class="status">
    <p data-testid="movies-error">Failed to load movies</p>
    <button mat-flat-button data-testid="movies-retry-button" (click)="retry()">Retry</button>
  </div>
} @else if (cards().length > 0) {
  <section class="movie-list" data-testid="movie-list">
    @for (card of cards(); track card.movie.id) {
      <mat-card appearance="outlined" class="movie-card" data-testid="movie-card" [attr.data-movie-id]="card.movie.id">
        <mat-card-content>
          <h2 data-testid="movie-title">{{ card.movie.title }}</h2>
          <p class="meta">
            <span data-testid="movie-genre">{{ card.movie.genre }}</span>
            <span data-testid="movie-runtime">{{ card.movie.runtimeMinutes }} min</span>
            <span data-testid="movie-format">{{ card.movie.format }}</span>
          </p>
          <div class="screenings">
            @for (screening of card.screenings; track screening.id) {
              <button
                mat-stroked-button
                data-testid="screening-button"
                [attr.data-screening-id]="screening.id"
                [routerLink]="['/screenings', screening.id, 'seats']"
              >
                {{ screening.time }}
              </button>
            }
          </div>
        </mat-card-content>
      </mat-card>
    }
  </section>
} @else {
  <p class="status" data-testid="movies-empty">No screenings on this day</p>
}
