export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideHttpClient(),
    provideRouter(appRoutes),
    provideNativeDateAdapter(),
  ],
};
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Movie, Screening } from './models';

export const API_BASE_URL = 'http://localhost:3000';

@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient);

  getMovies(): Observable<Movie[]> {
    return this.http.get<Movie[]>(`${API_BASE_URL}/movies`);
  }

  getScreeningsByDate(date: string): Observable<Screening[]> {
    return this.http.get<Screening[]>(`${API_BASE_URL}/screenings`, { params: { date } });
  }

  getScreening(id: string): Observable<Screening> {
    return this.http.get<Screening>(`${API_BASE_URL}/screenings/${encodeURIComponent(id)}`);
  }

  getMovie(id: number): Observable<Movie> {
    return this.http.get<Movie>(`${API_BASE_URL}/movies/${id}`);
  }
}
const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/** Formats a date as an ISO date (YYYY-MM-DD) using the browser's local calendar. */
export function toIsoDate(date: Date): string {
  const year = String(date.getFullYear()).padStart(4, '0');
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/** Parses a YYYY-MM-DD string into a local midnight Date; returns null for anything that is not a real calendar date. */
export function parseIsoDate(value: string | null | undefined): Date | null {
  if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return null;
  }
  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  if (toIsoDate(date) !== value) {
    return null;
  }
  return date;
}

/** Local midnight of the given date. */
export function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

/** Returns the date `days` days after `date`. */
export function addDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
}

/** English full weekday name, e.g. "Tuesday". */
export function weekdayName(date: Date): string {
  return WEEKDAYS[date.getDay()];
}

/** Show date as `<Weekday> <D> <Mon> <HH:mm>`, e.g. "Tuesday 15 Sep 16:00". */
export function formatShowDate(date: Date, time: string): string {
  return `${weekdayName(date)} ${date.getDate()} ${MONTHS[date.getMonth()]} ${time}`;
}
export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

import { Component, computed, effect, inject, resource } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { ActivatedRoute, Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { ApiService } from '../api.service';
import { formatShowDate, parseIsoDate } from '../dates';
import { Movie, Screening } from '../models';

type SeatState = 'available' | 'unavailable' | 'accessible';

interface SeatView {
  column: number;
  state: SeatState;
  gridColumn: string;
}

interface CouchView {
  start: number;
  end: number;
  state: Exclude<SeatState, 'accessible'>;
  gridColumn: string;
}

interface AisleView {
  gridColumn: string;
}

interface RowView {
  number: number;
  seats: SeatView[];
  couches: CouchView[];
  aisles: AisleView[];
}

const ROW_COUNT = 15;
const COLUMN_COUNT = 24;
const COUCH_ROW = 15;
/** Rows 1 to this number have no seats in columns 1–4 (the entrance). */
const ENTRANCE_LAST_ROW = 10;
/** Aisles sit after these columns; each is two grid tracks wide. */
const AISLE_AFTER_COLUMNS = [4, 20];
/** Grid tracks of the row labels; the seat columns occupy the tracks in between. */
const LEFT_LABEL_TRACK = 1;
const RIGHT_LABEL_TRACK = 30;

/**
 * Grid track of a seat column. Track 1 is the left row label, tracks 2–29 hold the seat
 * columns with each aisle taking two tracks, track 30 is the right row label.
 */
function gridTrack(column: number): number {
  return 1 + column + (column > 4 ? 2 : 0) + (column > 20 ? 2 : 0);
}

function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

function seatState(row: number, column: number, occupied: Set<string>): SeatState {
  if (occupied.has(seatId(row, column))) {
    return 'unavailable';
  }
  const accessible = row === 1 && column >= 10 && column <= 15;
  return accessible ? 'accessible' : 'available';
}

function buildRows(occupiedSeats: string[]): RowView[] {
  const occupied = new Set(occupiedSeats);
  return Array.from({ length: ROW_COUNT }, (_, index) => {
    const number = index + 1;
    const seats: SeatView[] = [];
    const couches: CouchView[] = [];

    if (number === COUCH_ROW) {
      for (let start = 1; start < COLUMN_COUNT; start += 2) {
        const end = start + 1;
        const unavailable =
          occupied.has(seatId(number, start)) || occupied.has(seatId(number, end));
        couches.push({
          start,
          end,
          state: unavailable ? 'unavailable' : 'available',
          gridColumn: `${gridTrack(start)} / span 2`,
        });
      }
    } else {
      const firstColumn = number <= ENTRANCE_LAST_ROW ? 5 : 1;
      for (let column = firstColumn; column <= COLUMN_COUNT; column++) {
        seats.push({
          column,
          state: seatState(number, column, occupied),
          gridColumn: String(gridTrack(column)),
        });
      }
    }

    const aisles = AISLE_AFTER_COLUMNS.map((column) => ({
      gridColumn: `${gridTrack(column) + 1} / span 2`,
    }));

    return { number, seats, couches, aisles };
  });
}

@Component({
  selector: 'app-seat-selection',
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly api = inject(ApiService);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  private readonly params = toSignal(this.route.paramMap, { requireSync: true });

  /** The screening id from the URL; undefined keeps the resource idle. */
  private readonly screeningId = computed(() => this.params().get('id') ?? undefined);

  readonly data = resource({
    params: () => this.screeningId(),
    loader: async ({ params: id }): Promise<{ screening: Screening; movie: Movie }> => {
      const screening = await firstValueFrom(this.api.getScreening(id));
      const movie = await firstValueFrom(this.api.getMovie(screening.movieId));
      return { screening, movie };
    },
  });

  readonly screening = computed(() => (this.data.hasValue() ? this.data.value().screening : null));

  readonly showDate = computed(() => {
    const screening = this.screening();
    const date = screening ? parseIsoDate(screening.date) : null;
    return screening && date ? formatShowDate(date, screening.time) : '';
  });

  readonly rows = computed<RowView[]>(() => {
    const screening = this.screening();
    return screening ? buildRows(screening.occupiedSeats) : [];
  });

  readonly leftLabelColumn = String(LEFT_LABEL_TRACK);
  readonly rightLabelColumn = String(RIGHT_LABEL_TRACK);

  constructor() {
    effect(() => {
      if (this.data.status() === 'error') {
        void this.router.navigate(['/']);
      }
    });
  }
}
