   117	        const ids = [seatId(number, start), seatId(number, end)];
   118	        couches.push({
   119	          start,
   120	          end,
   121	          ids,
   122	          state: stateOf(ids, false, occupied, selected),
   123	          gridColumn: `${gridTrack(start)} / span 2`,
