    38	  private readonly screeningId = computed(() => this.params().get('id') ?? undefined);
    39	
    40	  readonly data = resource({
    41	    params: () => this.screeningId(),
    42	    loader: async ({ params: id }): Promise<{ screening: Screening; movie: Movie }> => {
    43	      const screening = await firstValueFrom(this.api.getScreening(id));
    44	      const movie = await firstValueFrom(this.api.getMovie(screening.movieId));
    45	      return { screening, movie };
    46	    },
    47	  });
    48	
    49	  readonly screening = computed(() => (this.data.hasValue() ? this.data.value().screening : null));
    50	
    51	  /** Seat identifiers of the booking in progress; a removed ticket is taken out of it. */
    52	  private readonly seats = linkedSignal<string | undefined, string[]>({
    53	    source: this.screeningId,
    54	    computation: (id) => this.bookings.seatsFor(id),
    55	  });
    56	
    57	  readonly items = computed<SummaryItem[]>(() => {
    58	    if (!this.data.hasValue()) {
    59	      return [];
    60	    }
    61	    const { screening, movie } = this.data.value();
    62	    const datetime = `${screening.date} ${screening.time}`;
    63	    return ticketsFor(this.seats()).map((ticket) => ({
