    67	      datetime,
    68	      row: ticket.row,
    69	      seat: ticket.seat,
    70	      price: ticket.price,
    71	      priceLabel: formatPrice(ticket.price),
    72	    }));
    73	  });
    74	
    75	  readonly totalLabel = computed(() =>
    76	    formatPrice(this.items().reduce((total, item) => total + item.price, 0)),
    77	  );
