1	import { Component, computed, inject, resource } from '@angular/core';
2	import { toSignal } from '@angular/core/rxjs-interop';
3	import { MatButtonModule } from '@angular/material/button';
4	import { MatCardModule } from '@angular/material/card';
5	import { MatDatepickerModule } from '@angular/material/datepicker';
6	import { MatFormFieldModule } from '@angular/material/form-field';
7	import { MatInputModule } from '@angular/material/input';
8	import { ActivatedRoute, Router, RouterLink } from '@angular/router';
9	import { firstValueFrom, forkJoin } from 'rxjs';
10	import { ApiService } from '../api.service';
11	import { addDays, parseIsoDate, startOfDay, toIsoDate, weekdayName } from '../dates';
12	import { Movie, Screening } from '../models';
13	
14	interface DayButton {
15	  iso: string;
16	  label: string;
17	}
18	
19	interface MovieCard {
20	  movie: Movie;
21	  screenings: Screening[];
22	}
23	
24	@Component({
25	  selector: 'app-movie-list',
26	  imports: [MatButtonModule, MatCardModule, MatDatepickerModule, MatFormFieldModule, MatInputModule, RouterLink],
27	  templateUrl: './movie-list.html',
28	  styleUrl: './movie-list.scss',
29	})
30	export class MovieList {
31	  private readonly api = inject(ApiService);
32	  private readonly router = inject(Router);
33	  private readonly route = inject(ActivatedRoute);
34	
35	  private readonly today = startOfDay(new Date());
36	  private readonly todayIso = toIsoDate(this.today);
37	
38	  readonly minDate = this.today;
39	
40	  readonly dayButtons: DayButton[] = [0, 1, 2, 3, 4].map((offset) => {
41	    const date = addDays(this.today, offset);
42	    return { iso: toIsoDate(date), label: offset === 0 ? 'Today' : weekdayName(date) };
43	  });
44	
45	  private readonly queryParams = toSignal(this.route.queryParamMap, { requireSync: true });
46	
47	  /** The selected day as ISO date; a missing, invalid or past `date` selects today. */
48	  readonly selectedIso = computed(() => {
49	    const requested = this.queryParams().get('date');
50	    if (requested === null || parseIsoDate(requested) === null || requested < this.todayIso) {
51	      return this.todayIso;
52	    }
53	    return requested;
54	  });
55	
56	  readonly selectedDate = computed(() => parseIsoDate(this.selectedIso()));
57	
58	  readonly movies = resource({
59	    params: () => this.selectedIso(),
60	    loader: ({ params: date }) =>
61	      firstValueFrom(
62	        forkJoin({
63	          movies: this.api.getMovies(),
64	          screenings: this.api.getScreeningsByDate(date),
65	        }),
66	      ),
67	  });
68	
69	  /** One card per movie with at least one screening on the selected day, in backend order. */
70	  readonly cards = computed<MovieCard[]>(() => {
71	    if (!this.movies.hasValue()) {
72	      return [];
73	    }
74	    const { movies, screenings } = this.movies.value();
75	    return movies
76	      .map((movie) => ({
77	        movie,
78	        screenings: screenings
79	          .filter((screening) => screening.movieId === movie.id)
80	          .sort((a, b) => a.time.localeCompare(b.time)),
81	      }))
82	      .filter((card) => card.screenings.length > 0);
83	  });
84	
85	  retry(): void {
86	    this.movies.reload();
87	  }
88	
89	  selectDay(iso: string): void {
90	    this.navigateToDate(iso);
91	  }
92	
93	  onDatepickerChange(date: Date | null): void {
94	    if (!date) {
95	      return;
96	    }
97	    const iso = toIsoDate(date);
98	    this.navigateToDate(iso < this.todayIso ? this.todayIso : iso);
99	  }
100	
101	  private navigateToDate(iso: string): void {
102	    void this.router.navigate([], { relativeTo: this.route, queryParams: { date: iso } });
103	  }
104	}
